+    private boolean decodedMagnitude(int docId) throws IOException {
+        if (magnitudeIn == null) {
+            return false;
+        }
+        int currentDoc = magnitudeIn.docID();
+        if (docId == currentDoc) {
+            return true;
+        } else {
