+                settings.getAsBytesSize(
+                    BlockFactory.LOCAL_BREAKER_OVER_RESERVED_SIZE_SETTING,
+                    BlockFactory.LOCAL_BREAKER_OVER_RESERVED_DEFAULT_SIZE
